function UNIFIED_COMBINATORIAL_SOLVER(problem, time_limit)
    best ← null; memory ← INIT_MEMORY(problem); pool ← {GENERATE_INITIAL_PERM(problem)}
    while not STOP_CONDITION(time_limit, memory.iter):
        sol ← ADAPTIVE_CONSTRUCT(pool, memory, problem)           // builds/perturbs permutation/route/sequence
        sol ← HIERARCHICAL_REPAIR(sol, problem, memory)           // fix feasibility (capacity, precedence)
        sol ← ADAPTIVE_LOCAL_SEARCH(sol, problem, memory)         // multi-neighborhood, task-aware moves
        sol' ← PATH_RELINK(sol, SELECT_ELITE(pool, memory), problem, memory) // intensify by mixing elites
        for cand in {sol, sol'}:
            cand ← LEARNED_REPAIR_AND_EVAL(cand, problem, memory) // learned heuristics for constraint tuning
            if ACCEPT(cand, best, memory): update(best, pool, memory, cand)
        memory ← UPDATE_LEARNING_MODEL(memory, pool, problem)     // update stats, move gains, structural patterns
        pool ← DIVERSIFY_AND_TRIM(pool, memory, problem)          // maintain elite & diverse candidates
    return EXTRACT_PERMUTATION(best)                            // returns permutation(s) or route set per problem
end

